<?php if(!$listo): ?>
<?php if(Auth::tieneRol('admin')): ?><form method="post" action="<?= url('documentos/activar') ?>"><input type="hidden" name="_csrf" value="<?= e(Auth::csrfToken()) ?>"><button class="btn btn-primario">Activar archivo documental</button></form><?php else: ?><p>La administración está preparando el archivo documental.</p><?php endif; ?>
<?php else: ?>
<?php if($puedeSubir): ?><p><a class="btn btn-primario" href="<?= url('documentos/nuevo') ?>">Subir documento</a></p><?php endif; ?>
<form method="get" class="card formulario" style="max-width:1000px">
<label>Buscar por palabras clave, título o folio<input type="search" name="q" value="<?= e($q) ?>" maxlength="160" placeholder="Ej. tutoría, constancia o número de oficio"></label>
<details><summary>Filtrar documentos</summary><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,230px),1fr));gap:14px;margin-block:16px">
<?php foreach(['departamento_id'=>['Departamento',$departamentos],'coordinacion_id'=>['Coordinación',$coordinaciones],'programa_id'=>['Programa de estudios',$programas]] as $field=>[$label,$options]): ?><label><?= e($label) ?><select name="<?= e($field) ?>"><option value="">Todos</option><?php foreach($options as $o): ?><option value="<?= (int)$o['id'] ?>" <?= (string)$o['id']===($_GET[$field]??'')?'selected':'' ?>><?= e($o['nombre']) ?></option><?php endforeach; ?></select></label><?php endforeach; ?>
<label>Usuario que subió el documento<select name="subido_por"><option value="">Todos los disponibles</option><?php foreach($autores as $a): ?><option value="<?= (int)$a['id'] ?>" <?= (string)$a['id']===($_GET['subido_por']??'')?'selected':'' ?>><?= e($a['nombre']) ?></option><?php endforeach; ?></select></label>
<?php foreach(['subida_desde'=>'Subido desde','subida_hasta'=>'Subido hasta','documento_desde'=>'Fecha del documento desde','documento_hasta'=>'Fecha del documento hasta'] as $field=>$label): ?><label><?= e($label) ?><input type="date" name="<?= e($field) ?>" value="<?= e($_GET[$field]??'') ?>"></label><?php endforeach; ?>
<label>Estado<select name="estado"><option value="">Todos</option><option value="borrador" <?= ($_GET['estado']??'')==='borrador'?'selected':'' ?>>Borrador</option><option value="indizado" <?= ($_GET['estado']??'')==='indizado'?'selected':'' ?>>Indizado</option></select></label>
<label>Acciones relacionadas<select name="accion"><option value="">Todas</option><?php foreach(['pendiente'=>'Con tareas pendientes','completada'=>'Con tareas completadas','respuesta'=>'Con archivos de respuesta'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= ($_GET['accion']??'')===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label>
<label>Confidencialidad<select name="nivel"><option value="">Todas</option><option value="restringida" <?= ($_GET['nivel']??'')==='restringida'?'selected':'' ?>>Restringida</option><option value="confidencial" <?= ($_GET['nivel']??'')==='confidencial'?'selected':'' ?>>Confidencial</option></select></label>
</div></details><div><button class="btn btn-primario">Buscar</button> <a href="<?= url('documentos') ?>">Limpiar filtros</a></div></form>
<?php if(!$rows): ?><p>No hay documentos disponibles con estos filtros. Solo se muestran los que tienes permiso de consultar.</p><?php endif; ?>
<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,330px),1fr));gap:16px;margin-block:20px">
<?php foreach($rows as $r): ?><article class="card"><h2><a href="<?= url('documentos/'.$r['id']) ?>"><?= e($r['titulo']) ?></a></h2><p><?= e(ucfirst($r['estado'])) ?> · <?= e(ucfirst($r['nivel'])) ?> · #<?= (int)$r['id'] ?></p>
<dl><dt>Departamento / coordinación</dt><dd><?= e($r['departamento']) ?><?= $r['coordinacion']?' · '.e($r['coordinacion']):'' ?></dd><dt>Programa</dt><dd><?= e($r['programa']?:'No aplica') ?></dd><dt>Subido por</dt><dd><?= e($r['autor']) ?></dd><dt>Fecha de subida</dt><dd><?= e(fecha_corta($r['creado_en'])) ?></dd><dt>Fecha del documento</dt><dd><?= e($r['fecha_documento']?:'No aplica') ?></dd></dl></article><?php endforeach; ?></div>
<nav aria-label="Páginas de documentos"><?php if($page>1): ?><a class="btn" href="<?= url('documentos?'.http_build_query(array_merge($_GET,['pagina'=>$page-1]))) ?>">Anterior</a><?php endif; ?> <span>Página <?= $page ?></span> <?php if($more): ?><a class="btn" href="<?= url('documentos?'.http_build_query(array_merge($_GET,['pagina'=>$page+1]))) ?>">Siguiente</a><?php endif; ?></nav>
<?php endif; ?>
